import{_ as l,C as h,o,c as d,a5 as a,b as n,w as t,a as i,E as s,a6 as c}from"./chunks/framework.ym1pjj_g.js";const B=JSON.parse('{"title":"Implementation Overview","description":"","frontmatter":{},"headers":[],"relativePath":"implementation/implementation-overview.md","filePath":"implementation/implementation-overview.md","lastUpdated":1792687703000}'),p={name:"implementation/implementation-overview.md"};function u(m,e,g,b,f,C){const r=h("Mermaid");return o(),d("div",null,[e[2]||(e[2]=a('<h1 id="implementation-overview" tabindex="-1">Implementation Overview <a class="header-anchor" href="#implementation-overview" aria-label="Permalink to &quot;Implementation Overview&quot;">​</a></h1><p>TORCH extracts FHIR resources for a cohort as defined by a <a href="./../crtdl/crtdl.html">CRTDL</a>. An extraction runs as an asynchronous job: the CRTDL is validated when the job is submitted, and the job is then processed in three phases.</p><ol><li><strong>Cohort</strong> — determine the patients to extract.</li><li><strong>Patient batches</strong> — extract the patient-related data, one batch of patients at a time.</li><li><strong>Core</strong> — extract the core resources once for the whole job.</li></ol><h2 id="patient-resources-and-core-resources" tabindex="-1">Patient Resources and Core Resources <a class="header-anchor" href="#patient-resources-and-core-resources" aria-label="Permalink to &quot;Patient Resources and Core Resources&quot;">​</a></h2><p>TORCH splits all resources into two kinds, based on the FHIR <a href="https://hl7.org/fhir/R4/compartmentdefinition-patient.html" target="_blank" rel="noreferrer">Patient Compartment</a>:</p><ul><li><strong>Patient resources</strong> are resources <strong>within</strong> the patient compartment, e.g. <code>Patient</code>, <code>Condition</code>, <code>Observation</code> or <code>Encounter</code>. Each of them belongs to exactly one patient and is processed in that patient&#39;s batch.</li><li><strong>Core resources</strong> are resources <strong>outside</strong> the patient compartment, e.g. <code>Medication</code>, <code>Organization</code> or <code>Practitioner</code>. They do not belong to a single patient, can be referenced by many patients, and are processed once per job in the core phase.</li></ul><p>Whether a resource is a patient or a core resource depends only on its resource type, not on its content or profile. Attribute groups are split the same way: an attribute group whose resource type is in the patient compartment is a patient attribute group; all others are core attribute groups.</p>',7)),(o(),n(c,null,{default:t(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BCRTDL%5D%20--%3E%20B%7Bvalid%3F%7D%0A%20%20%20%20B%20--%3E%7Cno%7C%20C%5BError%5D%0A%20%20%20%20B%20--%3E%7Cyes%7C%20D%7Bpatient%20IDs%20given%3Cbr%2F%3Eas%20parameter%3F%7D%0A%20%20%20%20D%20--%3E%7Cno%7C%20E%5B%22Evaluate%20cohort%20definition%3Cbr%2F%3E(CQL%20or%20Flare)%22%5D%0A%20%20%20%20D%20--%3E%7Cyes%7C%20F%5BSplit%20patients%20into%20batches%5D%0A%20%20%20%20E%20--%3E%20F%0A%20%20%20%20F%20--%3E%20G%5BProcess%20patient%20batches%5D%0A%20%20%20%20G%20--%3E%20H%5BProcess%20core%20resources%5D%0A%20%20%20%20G%20--%3E%20I%5B%22Batch%20NDJSON%20files%22%5D%0A%20%20%20%20H%20--%3E%20J%5B%22core.ndjson%22%5D%0A%20%20%20%20class%20C%20errorNode%0A%20%20%20%20class%20I%20successNode%0A%20%20%20%20class%20J%20successNode%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a('<h2 id="job-submission" tabindex="-1">Job Submission <a class="header-anchor" href="#job-submission" aria-label="Permalink to &quot;Job Submission&quot;">​</a></h2><p>The CRTDL is <a href="./validation.html">validated</a> before the job is created. An invalid CRTDL is rejected immediately and no job is started. During validation, the attribute groups are annotated with the StructureDefinition information needed later on, so that this work is done only once per job.</p><h2 id="cohort" tabindex="-1">Cohort <a class="header-anchor" href="#cohort" aria-label="Permalink to &quot;Cohort&quot;">​</a></h2><p>If patient IDs are passed as a parameter, they are used as the cohort. Otherwise, the cohort definition of the CRTDL is evaluated, either with CQL on the FHIR server or with Flare. The resulting patients are split into batches (see <a href="./../configuration.html#torch-batchsize"><code>TORCH_BATCHSIZE</code></a>).</p><h2 id="patient-batches" tabindex="-1">Patient Batches <a class="header-anchor" href="#patient-batches" aria-label="Permalink to &quot;Patient Batches&quot;">​</a></h2><p>Each batch is processed independently; up to <a href="./../configuration.html#torch-maxconcurrency"><code>TORCH_MAXCONCURRENCY</code></a> batches run in parallel:</p><ol><li><strong>Consent</strong> — Fetch the consent resources of the batch&#39;s patients and calculate their consent periods. Patients without a matching consent are excluded. If no patient in the batch has consented, the batch is skipped. This step is skipped if the CRTDL contains no consent criteria. See <a href="./consent.html">Consent</a>.</li><li><strong>Direct Loading</strong> — Load the resources of all directly loaded patient attribute groups and assign them to their patients. Resources outside a patient&#39;s consent period are discarded. See <a href="./direct-load.html">Direct Loading</a>.</li><li><strong>Reference Resolution</strong> — Follow the references of the loaded resources and load the referenced resources that belong to linked attribute groups. See <a href="./reference-resolve.html">Reference Resolve</a>.</li><li><strong>Cascading Delete</strong> — Remove resources that failed a check (e.g. consent or must-have), together with all resources whose reference chain is broken by that removal. See <a href="./cascading-delete.html">Cascading Delete</a>.</li><li><strong>Must-Have Check</strong> — Exclude patients that no longer fulfill the must-have conditions of the directly loaded attribute groups. See <a href="./must-have.html">Must-Have Checking</a>.</li><li><strong>Extraction</strong> — Copy the selected attributes and redact everything else. See <a href="./data-extraction.html">Data Extraction</a> and <a href="./redaction.html">Redaction</a>.</li><li><strong>Write</strong> — Write one bundle per patient into the batch&#39;s NDJSON file. Resources outside the patient compartment that were referenced by the batch are passed on to the core phase.</li></ol><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><p>Once all batches are done, the core resources are processed in a single step:</p><ol><li><strong>Direct Loading</strong> — Load the resources of all directly loaded core attribute groups.</li><li><strong>Reference Resolution</strong> — Resolve the references of these resources.</li><li><strong>Cascading Delete</strong> — Remove resources that failed a check, together with the resources depending on them.</li><li><strong>Must-Have Check</strong> — Check the must-have conditions of the directly loaded core attribute groups. Because core resources are shared by all patients, a violation fails the whole job.</li><li><strong>Merge</strong> — Add the core resources referenced by the patient batches.</li><li><strong>Extraction</strong> — Copy and redact as for patient batches.</li><li><strong>Write</strong> — Write all core resources into a single bundle in <code>core.ndjson</code>.</li></ol>',10)),(o(),n(c,null,{default:t(()=>[s(r,{id:"mermaid-143",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Batch%5B%22Per%20patient%20batch%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20B1%5BConsent%5D%20--%3E%20B2%5BDirect%20Loading%5D%0A%20%20%20%20%20%20%20%20B2%20--%3E%20B3%5BReference%20Resolution%5D%0A%20%20%20%20%20%20%20%20B3%20--%3E%20B4%5BCascading%20Delete%5D%0A%20%20%20%20%20%20%20%20B4%20--%3E%20B5%5BMust-Have%20Check%5D%0A%20%20%20%20%20%20%20%20B5%20--%3E%20B6%5BExtraction%5D%0A%20%20%20%20%20%20%20%20B6%20--%3E%20B7%5B%22Write%20batch%20NDJSON%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Core%5B%22Once%20per%20job%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20C1%5BDirect%20Loading%5D%20--%3E%20C2%5BReference%20Resolution%5D%0A%20%20%20%20%20%20%20%20C2%20--%3E%20C3%5BCascading%20Delete%5D%0A%20%20%20%20%20%20%20%20C3%20--%3E%20C4%5BMust-Have%20Check%5D%0A%20%20%20%20%20%20%20%20C4%20--%3E%20C5%5BMerge%20referenced%3Cbr%2F%3Ecore%20resources%5D%0A%20%20%20%20%20%20%20%20C5%20--%3E%20C6%5BExtraction%5D%0A%20%20%20%20%20%20%20%20C6%20--%3E%20C7%5B%22Write%20core.ndjson%22%5D%0A%20%20%20%20end%0A%20%20%20%20B6%20-.-%3E%7Creferenced%20core%20resources%7C%20C5%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a('<h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>When the job has finished, the result consists of:</p><ul><li>one NDJSON file per patient batch, containing one bundle per patient,</li><li><code>core.ndjson</code>, containing the core resources,</li><li>diagnostic reports on excluded patients and resources (see <a href="./../api/diagnostics.html">Job Diagnostics</a>).</li></ul><p>The file URLs are listed in the job&#39;s completion manifest (see <a href="./../api/api.html">API</a>).</p>',4))])}const A=l(p,[["render",u]]);export{B as __pageData,A as default};
